+/**
+ * @brief 将 SoC 协议产生的 G-code 注入 Marlin 命令队列并标记在线指令上下文
+ * @param cmd G-code 零结尾字符串指针
+ */
+static void mc_proto_enqueue_gcode(const char *cmd)
+{
+    if (cmd == NULL)
+    {
+        return;
+    }
+    if (s_ap_enqueued_count < 255U)
+    {
+        s_ap_enqueued_count++;
+    }
+    s_ap_cmd_active = true;
+    enquecommand(cmd);
+    s_ap_cmd_active = false;
+}
+
+/**
+ * @brief 查询当前是否处于 SoC 在线协议注入指令处理期
+ * @return true 表示当前指令来自 SoC 在线协议，无需重复向 TH 广播
+ */
+bool minimc_proto_is_ap_cmd_active(void)
+{
+    return s_ap_cmd_active || (s_ap_enqueued_count > 0U);
+}
+
+/**
+ * @brief 消费一条由 SoC 在线协议注入 Marlin 队列的命令标记
+ * @return true 表示当前出队命令已由协议层完成状态与运动目标更新
+ */
+bool minimc_proto_consume_ap_enqueued(void)
+{
+    if (s_ap_enqueued_count > 0U)
+    {
+        s_ap_enqueued_count--;
+        return true;
+    }
+    return false;
+}
+
+/**
+ * @brief 构造并发送通用 MC 响应帧 (0x55 0xAA V2)
+ * @param resp_cmd 响应命令码
+ * @param seq 16位序列号
+ * @param payload 响应载荷指针 (可为 NULL)
+ * @param plen 响应载荷字节数
+ * @return true 发送成功，false 发送失败
+ */
+static bool send_mc_ack_frame(uint8_t resp_cmd, uint16_t seq, const void *payload, uint16_t plen)
+{
+    if (plen > MINIMC_MAX_PAYLOAD_SIZE)
+    {
+        return false;
+    }
+    uint8_t resp[MINIMC_MAX_FRAME_SIZE];
+    resp[0] = MINIMC_SOF_1;
+    resp[1] = MINIMC_SOF_2;
+    resp[2] = MINIMC_NODE_MC;
+    resp[3] = MINIMC_NODE_AP;
+    resp[4] = (uint8_t)(MINIMC_FLAG_IS_RESPONSE | MINIMC_FLAG_PROTO_V2);
+    resp[5] = resp_cmd;
+    resp[6] = MINIMC_DEFAULT_HOP_LIMIT;
+    resp[7] = MINIMC_DEFAULT_ROUTE;
+    resp[8] = (uint8_t)(seq & 0xFFU);
+    resp[9] = (uint8_t)((seq >> 8U) & 0xFFU);
+    resp[10] = (uint8_t)(plen & 0xFFU);
+    resp[11] = (uint8_t)((plen >> 8U) & 0xFFU);
+    if ((plen > 0U) && (payload != NULL))
+    {
+        const uint8_t *src = (const uint8_t *)payload;
+        for (uint16_t i = 0U; i < plen; ++i)
+        {
+            resp[MINIMC_HEADER_SIZE + i] = src[i];
+        }
+    }
+    const uint16_t body_len = (uint16_t)(MINIMC_HEADER_SIZE + plen);
+    const uint16_t crc = minimc_crc16(resp, body_len);
+    resp[body_len] = (uint8_t)(crc & 0xFFU);
+    resp[body_len + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);
+    return minimc_proto_send(resp, (uint16_t)(body_len + MINIMC_CRC_SIZE));
+}
+
+/**
+ * @brief 向 AP 发送 NACK 错误响应帧并记录 [MC-DBG] 日志
+ * @param frame 原始请求帧指针
+ * @param seq 16位请求序列号
+ * @param err_code 协议错误码
+ */
+static void send_mc_nack(const uint8_t *frame, uint16_t seq, uint8_t err_code)
+{
+    uint8_t resp[32];
+    uint16_t resp_len = 0U;
+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    const char *st_str = (err_code == 0x04U) ? "BAD_CMD" : "BAD_FRAME";
+    char kv[32];
+    mc_dbg_log_frame_err(frame, st_str, err_code);
+    build_nack_resp(seq, err_code, resp, &resp_len);
+    const bool tx_ok = minimc_proto_send(resp, resp_len);
+    (void)snprintf(kv, sizeof(kv), "err_code=0x%02X", (unsigned int)err_code);
+    const mc_dbg_meta_t nack_meta = { "TX", "MC", seq_u8, MINIMC_CMD_NACK, "NACK" };
+    mc_dbg_emit_tx_or_err(&nack_meta, kv, tx_ok);
+}
+
+/**
+ * @brief 发送 0x16 位置报告响应帧并输出 TX 调试日志
+ * @param seq 16位序列号
+ * @param op_str 操作类型描述字符串
+ */
+static void send_pos_query_ack(uint16_t seq, const char *op_str)
+{
+    uint8_t resp[64];
+    uint16_t resp_len = 0U;
+    char kv[160];
+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    build_pos_resp(seq, resp, &resp_len);
+    const bool tx_ok = minimc_proto_send(resp, resp_len);
+    mc_dbg_format_motion_kv(op_str, kv, sizeof(kv));
+    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_POS_QUERY, "ACK" };
+    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
+}
+
+/**
+ * @brief 发送 0x18 调平网格响应帧并输出 STATE 与 TX 调试日志
+ * @param seq 16位序列号
+ * @param probe_idx 探针点索引 (0~24)
+ */
+static void send_level_grid_ack(uint16_t seq, uint8_t probe_idx)
+{
+    uint8_t resp[128];
+    uint16_t resp_len = 0U;
+    char kv[160];
+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    build_level_grid_resp(seq, resp, &resp_len);
+    const bool tx_ok = ((resp_len > 0U) && (resp_len <= 128U)) ? minimc_proto_send(resp, resp_len) : false;
+    mc_dbg_format_level_kv("GRID_READ", probe_idx, kv, sizeof(kv));
+    mc_dbg_emit_state_and_tx(seq_u8, MINIMC_CMD_LEVEL_GRID_QUERY, kv, tx_ok);
+}
+
+/**
+ * @brief 处理 0x10 (SET_TEMP) 设定温度控制命令
+ * @param seq 16位序列号
+ * @param frame 完整请求帧指针
+ * @param plen 载荷长度
+ */
+static void handle_mc_set_temp(uint16_t seq, const uint8_t *frame, uint16_t plen)
+{
+    if (plen < sizeof(minimc_set_temp_req_t))
+    {
+        send_mc_nack(frame, seq, 0x02U);
+        return;
+    }
+    minimc_set_temp_req_t req;
+    (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
+    int16_t nozzle_ddC = s_dbg_state.nozzle_set_ddC;
+    int16_t bed_ddC = s_dbg_state.bed_set_ddC;
+    if (req.nozzle_target_deci_c >= 0)
+    {
+        nozzle_ddC = req.nozzle_target_deci_c;
+        Heater_set_target_temperature(&Extruder_One, (int16_t)(nozzle_ddC / 10));
+    }
+    if (req.bed_target_deci_c >= 0)
+    {
+        bed_ddC = req.bed_target_deci_c;
+        Heater_set_target_temperature(&Platform, (int16_t)(bed_ddC / 10));
+    }
+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    s_dbg_state.ack_seq = seq_u8;
+    mc_debug_notify_temp_target(nozzle_ddC, bed_ddC);
+    uint8_t resp[64];
+    uint16_t resp_len = 0U;
+    char kv[128];
+    build_temp_resp(seq, resp, &resp_len);
+    const bool tx_ok = minimc_proto_send(resp, resp_len);
+    mc_dbg_format_temp_kv(kv, sizeof(kv));
+    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_TEMP_REPORT, "ACK" };
+    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
+}
+
+/**
+ * @brief 处理 0x11 (MOTION_HOME) 归零控制命令 (兼容裸板防阻塞策略 A)
+ * @param seq 16位序列号
+ * @param frame 完整请求帧指针
+ * @param plen 载荷长度
+ */
+static void handle_mc_home(uint16_t seq, const uint8_t *frame, uint16_t plen)
+{
+    if ((plen > 0U) && (plen < sizeof(minimc_home_req_t)))
+    {
+        send_mc_nack(frame, seq, 0x02U);
+        return;
+    }
+    uint8_t axes_mask = 0x07U;
+    uint16_t feed = 1500U;
+    if (plen >= sizeof(minimc_home_req_t))
+    {
+        minimc_home_req_t req;
+        (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
+        axes_mask = ((req.axes_mask & 0x07U) == 0U) ? 0x07U : (uint8_t)(req.axes_mask & 0x07U);
+        feed = (req.feedrate_mm_s == 0U) ? 1500U : req.feedrate_mm_s;
+    }
+    char gcode[32];
+    (void)snprintf(
+        gcode,
+        sizeof(gcode),
+        "G28%s%s%s F%u",
+        ((axes_mask & 0x01U) != 0U) ? " X" : "",
+        ((axes_mask & 0x02U) != 0U) ? " Y" : "",
+        ((axes_mask & 0x04U) != 0U) ? " Z" : "",
+        (unsigned int)feed);
+    mc_proto_enqueue_gcode(gcode);
+    if ((axes_mask & 0x01U) != 0U)
+    {
+        current_position[X_AXIS] = 0.0f;
+        axis_known_position[X_AXIS] = true;
+    }
+    if ((axes_mask & 0x02U) != 0U)
+    {
+        current_position[Y_AXIS] = 0.0f;
+        axis_known_position[Y_AXIS] = true;
+    }
+    if ((axes_mask & 0x04U) != 0U)
+    {
+        current_position[Z_AXIS] = 0.0f;
+        axis_known_position[Z_AXIS] = true;
+    }
+    s_dbg_state.ack_seq = (uint8_t)(seq & 0xFFU);
+    mc_debug_notify_motion("HOME", axes_mask, feed);
+    send_pos_query_ack(seq, "HOME");
+}
