+/**
+ * @brief 处理 0x12 (MOTION_MOVE) 移动控制命令 (支持相对/绝对微米位移)
+ * @param seq 16位序列号
+ * @param frame 完整请求帧指针
+ * @param plen 载荷长度
+ */
+static void handle_mc_move(uint16_t seq, const uint8_t *frame, uint16_t plen)
+{
+    if (plen < sizeof(minimc_move_req_t))
+    {
+        send_mc_nack(frame, seq, 0x02U);
+        return;
+    }
+    minimc_move_req_t req;
+    (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
+    const uint16_t feed = (req.feedrate_mm_min == 0U) ? s_dbg_state.feed : req.feedrate_mm_min;
+    const float dx_mm = (float)req.x_um / 1000.0f;
+    const float dy_mm = (float)req.y_um / 1000.0f;
+    const float dz_mm = (float)req.z_um / 1000.0f;
+    if ((req.axes_mask & 0x01U) != 0U)
+    {
+        current_position[X_AXIS] = (req.is_relative != 0U) ? (current_position[X_AXIS] + dx_mm) : dx_mm;
+    }
+    if ((req.axes_mask & 0x02U) != 0U)
+    {
+        current_position[Y_AXIS] = (req.is_relative != 0U) ? (current_position[Y_AXIS] + dy_mm) : dy_mm;
+    }
+    if ((req.axes_mask & 0x04U) != 0U)
+    {
+        current_position[Z_AXIS] = (req.is_relative != 0U) ? (current_position[Z_AXIS] + dz_mm) : dz_mm;
+    }
+    char gcode[60];
+    (void)snprintf(
+        gcode,
+        sizeof(gcode),
+        "G1 X%.2f Y%.2f Z%.2f F%u",
+        (double)current_position[X_AXIS],
+        (double)current_position[Y_AXIS],
+        (double)current_position[Z_AXIS],
+        (unsigned int)feed);
+    mc_proto_enqueue_gcode(gcode);
+    s_dbg_state.ack_seq = (uint8_t)(seq & 0xFFU);
+    mc_debug_notify_motion("MOVE", req.axes_mask, feed);
+    send_pos_query_ack(seq, "MOVE");
+}
