+/**
+ * @brief 推进作业已完成行数并重算千分比进度
+ * @param step_lines 本批完成的行数增量
+ * @param out_dbg_state 输出调试状态枚举值
+ * @param out_resp_state 输出协议响应状态枚举值
+ */
+static void advance_job_step_lines(uint16_t step_lines, uint8_t *out_dbg_state, uint8_t *out_resp_state)
+{
+    is_paused = 0U;
+    const uint16_t step = (step_lines > 0U) ? step_lines : 1U;
+    if (s_job_total_lines == 0U)
+    {
+        s_job_total_lines = 100U;
+    }
+    const uint32_t next_lines = (uint32_t)s_job_executed_lines + (uint32_t)step;
+    s_job_executed_lines = (next_lines >= s_job_total_lines) ? s_job_total_lines : (uint16_t)next_lines;
+    s_dbg_state.progress_permille =
+        (uint16_t)(((uint32_t)s_job_executed_lines * 1000U) / (uint32_t)s_job_total_lines);
+    *out_dbg_state = (s_job_executed_lines >= s_job_total_lines) ? 4U : 2U;
+    *out_resp_state = (s_job_executed_lines >= s_job_total_lines) ? 3U : 1U;
+}
+
+/**
+ * @brief 根据 0x13 作业指令操作码更新作业状态机与真实行进度
+ * @param req 作业控制请求结构体指针
+ * @param out_dbg_state 输出调试状态枚举值
+ * @param out_resp_state 输出协议响应状态枚举值
+ */
+static void update_job_state_machine(const minimc_job_req_t *req, uint8_t *out_dbg_state, uint8_t *out_resp_state)
+{
+    if ((req == NULL) || (out_dbg_state == NULL) || (out_resp_state == NULL))
+    {
+        return;
+    }
+    if (req->job_op == 1U)
+    {
+        is_paused = 0U;
+        s_job_executed_lines = 0U;
+        s_job_total_lines = (req->total_lines > 0U) ? req->total_lines : 100U;
+        s_dbg_state.progress_permille = 0U;
+        *out_dbg_state = 2U;
+        *out_resp_state = 1U;
+        return;
+    }
+    if ((req->job_op == 2U) || (req->job_op == 3U))
+    {
+        is_paused = (req->job_op == 2U) ? 1U : 0U;
+        *out_dbg_state = (req->job_op == 2U) ? 3U : 2U;
+        *out_resp_state = (req->job_op == 2U) ? 2U : 1U;
+        return;
+    }
+    if (req->job_op == 4U)
+    {
+        advance_job_step_lines(req->total_lines, out_dbg_state, out_resp_state);
+        return;
+    }
+    is_paused = 0U;
+    s_job_executed_lines = 0U;
+    s_job_total_lines = 0U;
+    s_dbg_state.progress_permille = 0U;
+    *out_dbg_state = 0U;
+    *out_resp_state = 0U;
+}
+
+/**
+ * @brief 处理 0x13 (JOB_CONTROL) 作业状态与进度控制命令
+ * @param seq 16位序列号
+ * @param frame 完整请求帧指针
+ * @param plen 载荷长度
+ */
+static void handle_mc_job_control(uint16_t seq, const uint8_t *frame, uint16_t plen)
+{
+    if (plen < sizeof(minimc_job_req_t))
+    {
+        send_mc_nack(frame, seq, 0x02U);
+        return;
+    }
+    minimc_job_req_t req;
+    (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
+    uint8_t dbg_state = 0U;
+    uint8_t resp_state = 0U;
+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    update_job_state_machine(&req, &dbg_state, &resp_state);
+    mc_debug_notify_job(dbg_state, s_dbg_state.progress_permille, seq_u8);
+    minimc_job_resp_t resp_pay;
+    resp_pay.job_state = resp_state;
+    resp_pay.ack_seq = seq_u8;
+    resp_pay.progress_permille = s_dbg_state.progress_permille;
+    resp_pay.executed_lines = s_job_executed_lines;
+    resp_pay.total_lines = s_job_total_lines;
+    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_JOB_CONTROL, seq, &resp_pay, sizeof(resp_pay));
+    char kv[128];
+    mc_dbg_format_job_kv(kv, sizeof(kv));
+    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_JOB_CONTROL, "ACK" };
+    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
+}
