+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    s_dbg_state.ack_seq = seq_u8;
+    mc_debug_notify_motion("STOP", 0U, 0U);
+    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_ACK, seq, NULL, 0U);
