+    char gcode[61];
+    (void)memcpy(gcode, frame + MINIMC_HEADER_SIZE + 2U, line_len);
+    gcode[line_len] = '\0';
+    mc_proto_enqueue_gcode(gcode);
+    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
+    mc_apply_gcode_side_effects(gcode, seq_u8);
+    minimc_gcode_resp_t resp_pay = { 0U, 4U, seq };
+    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_GCODE_EXEC, seq, &resp_pay, sizeof(resp_pay));
+    char kv[96];
+    (void)snprintf(kv, sizeof(kv), "gcode_len=%u status=OK", (unsigned int)line_len);
+    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_GCODE_EXEC, "ACK" };
+    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
+}
