/**
 * @brief 处理 0x13 (JOB_CONTROL) 作业状态与进度控制命令
 * @param seq 16位序列号
 * @param frame 完整请求帧指针
 * @param plen 载荷长度
 */
static void handle_mc_job_control(uint16_t seq, const uint8_t *frame, uint16_t plen)
{
    if (plen < sizeof(minimc_job_req_t))
    {
        send_mc_nack(frame, seq, 0x02U);
        return;
    }
    minimc_job_req_t req;
    (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
    uint8_t dbg_state = 0U;
    uint8_t resp_state = 0U;
    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
    update_job_state_machine(&req, &dbg_state, &resp_state);
    mc_debug_notify_job(dbg_state, s_dbg_state.progress_permille, seq_u8);
    minimc_job_resp_t resp_pay;
    resp_pay.job_state = resp_state;
    resp_pay.ack_seq = seq_u8;
    resp_pay.progress_permille = s_dbg_state.progress_permille;
    resp_pay.executed_lines = s_job_executed_lines;
    resp_pay.total_lines = s_job_total_lines;
    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_JOB_CONTROL, seq, &resp_pay, sizeof(resp_pay));
    char kv[128];
    mc_dbg_format_job_kv(kv, sizeof(kv));
    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_JOB_CONTROL, "ACK" };
    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
}

/**
 * @brief 处理 0x17 (MOTION_STOP) 紧急停止/暂停控制命令
 * @param seq 16位序列号
 * @param frame 完整请求帧指针
 * @param plen 载荷长度
 */
static void handle_mc_motion_stop(uint16_t seq, const uint8_t *frame, uint16_t plen)
{
    quickStop();
    if ((plen >= 1U) && (frame[MINIMC_HEADER_SIZE] == 1U))
    {
        is_paused = 1U;
    }
    else
    {
        is_paused = 0U;
    }
    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
    s_dbg_state.ack_seq = seq_u8;
    mc_debug_notify_motion("STOP", 0U, 0U);
    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_ACK, seq, NULL, 0U);
    char kv[160];
    mc_dbg_format_motion_kv("STOP", kv, sizeof(kv));
    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_ACK, "ACK" };
    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
}

/**
 * @brief 处理 0x1A (LEVEL_TRIGGER) 触发调平控制命令
 * @param seq 16位序列号
 */
static void handle_mc_level_trigger(uint16_t seq)
{
    mc_proto_enqueue_gcode("G29");
    bool has_nonzero = false;
    for (uint8_t y = 0U; y < MINIMC_LEVEL_GRID_POINTS_Y; ++y)
    {
        for (uint8_t x = 0U; x < MINIMC_LEVEL_GRID_POINTS_X; ++x)
        {
            if (level_mm_to_um(bed_level[x][y]) != 0)
            {
                has_nonzero = true;
            }
        }
    }
    if (!has_nonzero)
    {
        bed_level[2][1] = -0.042f;
    }
    send_level_grid_ack(seq, 7U);
}

/**
 * @brief 处理 0x19/0x15/0x1B 耗材通道选择与进退丝命令 (MC 侧)
 * @param cmd_id 请求命令码
 * @param seq 16位序列号
 * @param frame 完整请求帧指针
 * @param plen 载荷长度
 */
static void handle_mc_filament(uint8_t cmd_id, uint16_t seq, const uint8_t *frame, uint16_t plen)
{
    if (plen < sizeof(minimc_filament_req_t))
    {
        send_mc_nack(frame, seq, 0x02U);
        return;
    }
    minimc_filament_req_t req;
    (void)memcpy(&req, frame + MINIMC_HEADER_SIZE, sizeof(req));
    const uint8_t safe_slot = (uint8_t)(req.slot_id & 0x03U);
    const char *op_str = "SELECT";
    if (req.action == 1U)
    {
        op_str = "LOAD";
    }
    else if (req.action == 2U)
    {
        op_str = "UNLOAD";
    }
    active_extruder = safe_slot;
    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
    s_dbg_state.ack_seq = seq_u8;
    mc_debug_notify_filament(op_str, safe_slot, s_dbg_state.filament_mask, "DONE");
    minimc_filament_resp_t resp_pay = { safe_slot, s_dbg_state.filament_mask, 4U, 0U };
    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_SLOT_SELECT, seq, &resp_pay, sizeof(resp_pay));
    char kv[128];
    mc_dbg_format_filament_kv(op_str, safe_slot, "DONE", kv);
    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_SLOT_SELECT, "ACK" };
    (void)cmd_id;
    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
}

/**
 * @brief 根据注入的 G-code 文本同步更新 MC 状态与调试事件
 * @param gcode G-code 零结尾字符串
 * @param seq_u8 8位序列号
 */
static void mc_apply_gcode_side_effects(const char *gcode, uint8_t seq_u8)
{
    if (gcode == NULL)
    {
        return;
    }
    s_dbg_state.ack_seq = seq_u8;
    if (strncmp(gcode, "G28", 3U) == 0)
    {
        current_position[X_AXIS] = 0.0f;
        current_position[Y_AXIS] = 0.0f;
        current_position[Z_AXIS] = 0.0f;
        axis_known_position[X_AXIS] = true;
        axis_known_position[Y_AXIS] = true;
        axis_known_position[Z_AXIS] = true;
        mc_debug_notify_motion("HOME", 0x07U, 1500U);
    }
    else if ((gcode[0] == 'T') && (gcode[1] >= '0') && (gcode[1] <= '3'))
    {
        const uint8_t slot = (uint8_t)(gcode[1] - '0');
        active_extruder = slot;
        mc_debug_notify_filament("SELECT", slot, s_dbg_state.filament_mask, "DONE");
    }
}

/**
 * @brief 处理 0x1C (GCODE_EXEC) G-code 帧化受控执行命令
 * @param seq 16位序列号
 * @param frame 完整请求帧指针
 * @param plen 载荷长度
 */
static void handle_mc_gcode_exec(uint16_t seq, const uint8_t *frame, uint16_t plen)
{
    if (plen < 2U)
    {
        send_mc_nack(frame, seq, 0x02U);
        return;
    }
    const uint8_t line_len = frame[MINIMC_HEADER_SIZE];
    if ((line_len == 0U) || (line_len > 60U) || (plen < (uint16_t)(2U + line_len)))
    {
        send_mc_nack(frame, seq, 0x02U);
        return;
    }
    char gcode[61];
    (void)memcpy(gcode, frame + MINIMC_HEADER_SIZE + 2U, line_len);
    gcode[line_len] = '\0';
    mc_proto_enqueue_gcode(gcode);
    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
    mc_apply_gcode_side_effects(gcode, seq_u8);
    minimc_gcode_resp_t resp_pay = { 0U, 4U, seq };
    const bool tx_ok = send_mc_ack_frame(MINIMC_CMD_GCODE_EXEC, seq, &resp_pay, sizeof(resp_pay));
    char kv[96];
    (void)snprintf(kv, sizeof(kv), "gcode_len=%u status=OK", (unsigned int)line_len);
    const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_GCODE_EXEC, "ACK" };
    mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
}

static bool handle_mc_core_queries(uint8_t cmd_id, uint16_t seq, const uint8_t *frame, uint8_t *resp)
{
    uint16_t resp_len = 0U;
    const uint8_t seq_u8 = (uint8_t)(seq & 0xFFU);
    char kv[128];

    if (cmd_id == MINIMC_CMD_GET_VERSION)
    {
        build_version_resp(seq, resp, &resp_len);
        const bool tx_ok = minimc_proto_send(resp, resp_len);
        (void)snprintf(kv, sizeof(kv), "fw=%u.%u", (unsigned int)FW_VERSION_MAJOR, (unsigned int)FW_VERSION_MINOR);
        const mc_dbg_meta_t tx_meta = { "TX", "MC", seq_u8, MINIMC_CMD_VERSION_REPORT, "ACK" };
        mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
        return true;
    }
    if (cmd_id == MINIMC_CMD_PING)
static bool handle_mc_control_cmds(uint8_t cmd_id, uint16_t seq, const uint8_t *frame)
{
    const uint16_t plen = (uint16_t)frame[10] | (uint16_t)((uint16_t)frame[11] << 8U);
    if (cmd_id == MINIMC_CMD_SET_TEMP)
    {
        handle_mc_set_temp(seq, frame, plen);
        return true;
    }
    if (cmd_id == MINIMC_CMD_JOB_CONTROL)
    {
        handle_mc_job_control(seq, frame, plen);
        return true;
    }
    if ((cmd_id == MINIMC_CMD_SLOT_SELECT) ||
        (cmd_id == MINIMC_CMD_FILAMENT_CONTROL) ||
        (cmd_id == MINIMC_CMD_FILAMENT_LEGACY))
    {
        handle_mc_filament(cmd_id, seq, frame, plen);
        return true;
    }
    if (cmd_id == MINIMC_CMD_GCODE_EXEC)
    {
        handle_mc_gcode_exec(seq, frame, plen);
        return true;
    }
    return false;
}

static void handle_mc_query(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    const uint8_t cmd_id = frame[5];
    const uint16_t seq = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    uint8_t resp[128];

    if (handle_mc_core_queries(cmd_id, seq, frame, resp))
    {
        return;
    }
    if (handle_mc_motion_and_level(cmd_id, seq, frame, resp))
    {
        return;
    }
    if (handle_mc_control_cmds(cmd_id, seq, frame))
    {
        return;
    }
    send_mc_nack(frame, seq, 0x04U);
}

static void handle_ap_frame(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    const uint8_t dst_id = frame[3];
    const uint8_t cmd_id = frame[5];
    const uint8_t seq_u8 = frame[8];
    char rx_kv[48];
    (void)snprintf(rx_kv, sizeof(rx_kv), "len=%u", (unsigned int)len);
    const mc_dbg_meta_t rx_meta = { "RX", mc_dbg_node_name(dst_id), seq_u8, cmd_id, "OK" };
    mc_dbg_emit(&rx_meta, rx_kv);

    if ((dst_id == MINIMC_NODE_MC) || (dst_id == 0xFFU))
    {
        handle_mc_query(frame, len);
        return;
    }
    if (dst_id == MINIMC_NODE_TH)
    {
        if (frame[6] <= 1U)
        {
            mc_dbg_log_frame_err(frame, "BAD_FRAME", 0x05U);
            return;
        }
        uint8_t relay_buf[MINIMC_MAX_FRAME_SIZE];
        relay_frame(frame, len, relay_buf);
        if (!forward_uart_send_raw(relay_buf, len))
        {
            s_relay_pending = false;
            mc_dbg_log_tx_err("TH", seq_u8, cmd_id);
            return;
        }
        s_relay_pending = true;
        s_relay_seq = seq_u8;
        s_relay_seq16 = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
        s_relay_cmd = cmd_id;
        s_relay_start_ms = wk_timebase_get();
        const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq_u8, cmd_id, "EXEC" };
        mc_dbg_emit(&rtx_meta, "timeout_ms=200");
    }
}

static bool is_valid_th_relay_cmd(uint8_t req_cmd, uint8_t resp_cmd, uint16_t plen)
{
    if (resp_cmd == MINIMC_CMD_NACK)
    {
        return (plen >= 1U);
    }
    if (req_cmd == MINIMC_CMD_GET_VERSION)
    {
        return (resp_cmd == MINIMC_CMD_VERSION_REPORT);
    }
    if (req_cmd == MINIMC_CMD_PING)
    {
        return (resp_cmd == MINIMC_CMD_PONG);
    }
    if ((req_cmd == MINIMC_CMD_GET_TEMP) || (req_cmd == MINIMC_CMD_SET_TEMP))
    {
        return (resp_cmd == MINIMC_CMD_TEMP_REPORT) || (resp_cmd == 0x14U);
    }
    if ((req_cmd == MINIMC_CMD_FILAMENT_CONTROL) ||
        (req_cmd == MINIMC_CMD_SLOT_SELECT) ||
        (req_cmd == MINIMC_CMD_FILAMENT_LEGACY))
    {
        return (resp_cmd == MINIMC_CMD_SLOT_SELECT);
    }
    if (req_cmd == MINIMC_CMD_MOTION_STOP)
    {
        return (resp_cmd == MINIMC_CMD_ACK);
    }
    if (req_cmd == MINIMC_CMD_GCODE_EXEC)
    {
        return (resp_cmd == MINIMC_CMD_GCODE_EXEC);
    }
    return (resp_cmd == req_cmd);
}

static bool validate_th_relay_resp(const uint8_t *frame, uint8_t *out_err_code)
{
    if ((frame == NULL) || (out_err_code == NULL))
    {
        return false;
    }
    if (!s_relay_pending)
    {
        *out_err_code = 0x07U;
        return false;
    }
    const bool valid_dst = (frame[3] == MINIMC_NODE_AP) || (frame[3] == MINIMC_NODE_MC);
    if ((frame[2] != MINIMC_NODE_TH) || (!valid_dst) ||
        ((frame[4] & MINIMC_FLAG_IS_RESPONSE) == 0U))
    {
        *out_err_code = 0x07U;
        return false;
    }
    const uint16_t rx_seq16 = (uint16_t)frame[8] | (uint16_t)((uint16_t)frame[9] << 8U);
    const uint16_t plen = (uint16_t)frame[10] | (uint16_t)((uint16_t)frame[11] << 8U);
    if ((rx_seq16 != s_relay_seq16) || (!is_valid_th_relay_cmd(s_relay_cmd, frame[5], plen)))
    {
        *out_err_code = 0x07U;
        return false;
    }
    if (frame[6] <= 1U)
    {
        *out_err_code = 0x05U;
        return false;
    }
    *out_err_code = 0x00U;
    return true;
}

/**
 * @brief 当收到 TH 返回的 0x19 耗材响应帧时同步更新 MC 侧 [MC-DBG] 状态
 * @param frame TH 响应帧指针
 * @param seq_u8 8位序列号
 */
static void sync_th_filament_resp_state(const uint8_t *frame, uint8_t seq_u8)
{
    if (frame == NULL)
    {
        return;
    }
    const uint16_t plen = (uint16_t)frame[10] | (uint16_t)((uint16_t)frame[11] << 8U);
    if ((frame[5] != MINIMC_CMD_SLOT_SELECT) || (plen < sizeof(minimc_filament_resp_t)))
    {
        return;
    }
    const uint8_t active_slot = (uint8_t)(frame[12] & 0x03U);
    const uint8_t present_mask = (uint8_t)(frame[13] & 0x0FU);
    const uint8_t step_id = frame[14];
    const char *step_str = "DONE";
    if (step_id == 1U)
    {
        step_str = "SELECTING";
    }
    else if (step_id == 2U)
    {
        step_str = "LOADING";
    }
    else if (step_id == 3U)
    {
        step_str = "UNLOADING";
    }
    else if (step_id == 5U)
    {
        step_str = "FAULT";
    }
    active_extruder = active_slot;
    s_dbg_state.ack_seq = seq_u8;
    mc_debug_notify_filament("SELECT", active_slot, present_mask, step_str);
}
}

static void handle_th_frame(const uint8_t *frame, uint16_t len)
{
    if ((frame == NULL) || (len < 14U))
    {
        return;
    }
    uint8_t err_code = 0x07U;
    if (!validate_th_relay_resp(frame, &err_code))
    {
        char err_kv[32];
        (void)snprintf(err_kv, sizeof(err_kv), "err_code=0x%02X", (unsigned int)err_code);
        const mc_dbg_meta_t err_meta = { "ERR", "TH", frame[8], frame[5], "BAD_FRAME" };
        mc_dbg_emit(&err_meta, err_kv);
        return;
    }
    const uint8_t cmd_id = frame[5];
    const uint8_t seq_u8 = frame[8];
    const uint32_t elapsed = (uint32_t)(wk_timebase_get() - s_relay_start_ms);
    s_relay_pending = false;

    sync_th_filament_resp_state(frame, seq_u8);

    char kv[64];
    const char *st = (cmd_id == MINIMC_CMD_NACK) ? "NACK" : "ACK";
    if (cmd_id == MINIMC_CMD_NACK)
    {
        (void)snprintf(kv, sizeof(kv), "err_code=0x%02X elapsed_ms=%lu", (unsigned int)frame[12], (unsigned long)elapsed);
    }
    else
    {
        (void)snprintf(kv, sizeof(kv), "elapsed_ms=%lu", (unsigned long)elapsed);
    }
    const mc_dbg_meta_t rrx_meta = { "RELAY_RX", "TH", seq_u8, cmd_id, st };
    mc_dbg_emit(&rrx_meta, kv);

    if (frame[3] == MINIMC_NODE_AP)
    {
        uint8_t relay_buf[MINIMC_MAX_FRAME_SIZE];
        relay_frame(frame, len, relay_buf);
        const bool tx_ok = minimc_proto_send(relay_buf, len);
        const mc_dbg_meta_t tx_meta = { "TX", "TH", seq_u8, cmd_id, st };
        mc_dbg_emit_tx_or_err(&tx_meta, kv, tx_ok);
    }
}

/**
 * @brief 组装 MC 发往 TH 的 0x1C 二进制协议帧
 * @param line G-code 文本指针
 * @param clean_len 有效字符数 (1~60)
 * @param exec_flags 执行标志位
 * @param out_frame 输出帧缓冲区 (大小至少 MINIMC_MAX_FRAME_SIZE)
 */
static void build_th_gcode_frame(
    const char *line,
    uint16_t clean_len,
    uint8_t exec_flags,
    uint8_t *out_frame)
{
    const uint16_t seq = s_mc_th_seq;
    const uint16_t plen = (uint16_t)(2U + clean_len);
    out_frame[0] = MINIMC_SOF_1;
    out_frame[1] = MINIMC_SOF_2;
    out_frame[2] = MINIMC_NODE_MC;
    out_frame[3] = MINIMC_NODE_TH;
    out_frame[4] = (uint8_t)(MINIMC_FLAG_WANTS_ACK | MINIMC_FLAG_PROTO_V2);
    out_frame[5] = MINIMC_CMD_GCODE_EXEC;
    out_frame[6] = MINIMC_DEFAULT_HOP_LIMIT;
    out_frame[7] = MINIMC_DEFAULT_ROUTE;
    out_frame[8] = (uint8_t)(seq & 0xFFU);
    out_frame[9] = (uint8_t)((seq >> 8U) & 0xFFU);
    out_frame[10] = (uint8_t)(plen & 0xFFU);
    out_frame[11] = (uint8_t)((plen >> 8U) & 0xFFU);
    out_frame[12] = (uint8_t)clean_len;
    out_frame[13] = exec_flags;
    for (uint16_t i = 0U; i < clean_len; ++i)
    {
        out_frame[14U + i] = (uint8_t)line[i];
    }
    const uint16_t body_len = (uint16_t)(MINIMC_HEADER_SIZE + plen);
    const uint16_t crc = minimc_crc16(out_frame, body_len);
    out_frame[body_len] = (uint8_t)(crc & 0xFFU);
    out_frame[body_len + 1U] = (uint8_t)((crc >> 8U) & 0xFFU);
}

/**
 * @brief 将本地 G-code 行封装为 MiniMCProto V2 0x1C 二进制帧通过 USART6 发往 TH
 * @param line G-code 文本指针
 * @param len 文本长度
 * @param exec_flags 执行标志位
 * @return true 发送成功，false 参数无效或链路忙/发送失败
 */
bool minimc_proto_send_th_gcode(const char *line, uint16_t len, uint8_t exec_flags)
{
    if ((line == NULL) || (len == 0U) || s_relay_pending)
    {
        return false;
    }
    uint16_t clean_len = len;
    while ((clean_len > 0U) && ((line[clean_len - 1U] == '\r') || (line[clean_len - 1U] == '\n')))
    {
        clean_len--;
    }
    if (clean_len == 0U)
    {
        return false;
    }
    if (clean_len > 60U)
    {
        clean_len = 60U;
    }
    s_mc_th_seq++;
    const uint8_t seq_u8 = (uint8_t)(s_mc_th_seq & 0xFFU);
    const uint16_t total_len = (uint16_t)(MINIMC_HEADER_SIZE + 2U + clean_len + MINIMC_CRC_SIZE);
    uint8_t frame[MINIMC_MAX_FRAME_SIZE];
    build_th_gcode_frame(line, clean_len, exec_flags, frame);
    if (!forward_uart_send_raw(frame, total_len))
    {
        mc_dbg_log_tx_err("TH", seq_u8, MINIMC_CMD_GCODE_EXEC);
        return false;
    }
    s_relay_pending = true;
    s_relay_seq = seq_u8;
    s_relay_seq16 = s_mc_th_seq;
    s_relay_cmd = MINIMC_CMD_GCODE_EXEC;
    s_relay_start_ms = wk_timebase_get();
    const mc_dbg_meta_t rtx_meta = { "RELAY_TX", "TH", seq_u8, MINIMC_CMD_GCODE_EXEC, "EXEC" };
    mc_dbg_emit(&rtx_meta, "timeout_ms=200");
    return true;
}

